<script lang="ts">
  import { Check, CircleAlert, Code2, LoaderCircle, Moon, PlugZap, RotateCcw, Sun } from 'lucide-svelte';
  import { DEFAULT_API_BASE_URL, getApiBaseUrl, setApiBaseUrl } from '../api/client';
  import { theme } from '../stores/theme.svelte';
  import { toasts } from '../stores/toasts.svelte';
  let apiUrl = $state(getApiBaseUrl()); let status = $state<'idle' | 'checking' | 'online' | 'offline'>('idle'); let statusMessage = $state('Not checked');
  $effect(() => { void testConnection(); });
  async function testConnection(url = apiUrl) { status = 'checking'; statusMessage = 'Checking connection…'; try { const response = await fetch(`${url.replace(/\/$/, '')}/`, { headers: { Accept: 'text/plain, application/json' } }); if (!response.ok) throw new Error(`HTTP ${response.status}`); status = 'online'; statusMessage = 'Connected'; } catch (cause) { status = 'offline'; statusMessage = cause instanceof Error ? cause.message : 'Unavailable'; } }
  async function save() { setApiBaseUrl(apiUrl); apiUrl = getApiBaseUrl(); await testConnection(apiUrl); toasts.show(status === 'online' ? 'success' : 'info', 'API URL saved', status === 'online' ? 'Connection verified.' : 'The URL was saved, but the API is not reachable right now.'); }
  function resetUrl() { setApiBaseUrl(''); apiUrl = DEFAULT_API_BASE_URL; void testConnection(apiUrl); }
</script>
<div class="page-wrap max-w-5xl"><section class="mb-6"><p class="eyebrow">Preferences</p><h2 class="page-heading">Settings</h2><p class="page-description">Tune your local JobHunter workspace.</p></section><div class="space-y-4">
  <section class="panel overflow-hidden"><div class="settings-row items-start"><div class="settings-icon"><PlugZap class="size-4" /></div><div class="min-w-0 flex-1"><h3 class="section-title">API connection</h3><p class="section-subtitle">The frontend uses this URL for every backend request.</p><div class="mt-4 flex flex-col gap-2 sm:flex-row"><input class="input flex-1 font-mono text-[11px]" bind:value={apiUrl} aria-label="Backend URL" /><button class="button primary" onclick={save}>Save & test</button><button class="icon-button h-9 w-9" aria-label="Reset API URL" title="Reset to environment default" onclick={resetUrl}><RotateCcw class="size-3.5" /></button></div><p class="mt-2 text-[10px] text-[var(--faint)]">Default: <code>{DEFAULT_API_BASE_URL}</code>. In development, <code>/api</code> is proxied to <code>http://localhost:3000</code>.</p></div><span class:online={status === 'online'} class:offline={status === 'offline'} class="connection-badge">{#if status === 'checking'}<LoaderCircle class="size-3 animate-spin" />{:else if status === 'online'}<Check class="size-3" />{:else}<CircleAlert class="size-3" />{/if}{statusMessage}</span></div></section>
  <section class="panel overflow-hidden"><div class="settings-row"><div class="settings-icon">{#if theme.value === 'dark'}<Moon class="size-4" />{:else}<Sun class="size-4" />{/if}</div><div class="flex-1"><h3 class="section-title">Appearance</h3><p class="section-subtitle">Theme preference is stored in this browser.</p></div><div class="segmented"><button class:active={theme.value === 'dark'} onclick={() => (theme.value = 'dark')}><Moon class="size-3.5" /> Dark</button><button class:active={theme.value === 'light'} onclick={() => (theme.value = 'light')}><Sun class="size-3.5" /> Light</button></div></div></section>
  <section class="panel overflow-hidden"><div class="settings-row items-start"><div class="settings-icon"><Code2 class="size-4" /></div><div class="flex-1"><h3 class="section-title">About JobHunter</h3><p class="section-subtitle">A personal job aggregation and tracking workspace.</p><dl class="mt-4 grid max-w-md grid-cols-[100px_1fr] gap-y-2 text-[11px]"><dt class="text-[var(--faint)]">Frontend</dt><dd class="text-[var(--muted)]">Svelte 5 · TypeScript · Tailwind CSS 4</dd><dt class="text-[var(--faint)]">Backend</dt><dd class="text-[var(--muted)]">NestJS · PostgreSQL</dd><dt class="text-[var(--faint)]">Version</dt><dd class="text-[var(--muted)]">0.1.0</dd></dl></div><span class="source-pill">Local</span></div></section>
</div></div>
